  { label: '반려', value: 'X' },
];

// ─────────────────── State ──────────────────────────────────────────────────────────
const allRows = ref<RowItem[]>([...MOCK_DATA]);

const state = reactive({
  loading:     false,
  selectedRow: null as RowItem | null,
  pageSize:    20,
  page:        { first: 0, rows: 20 },
});

const searchParams = reactive({
  vocDateRangeFrom: '',
  vocDateRangeTo: '',
  supplierName: '',
  materialName: '',
  vocStatus: '',
  isUrgent: '',
});

// ─────────────────── Computed ───────────────────────────────────────────────────────
const filteredRows = computed<RowItem[]>(() => {
  let rows = allRows.value;
  if (searchParams.vocDateRangeFrom) rows = rows.filter(r => r.vocDateRange >= searchParams.vocDateRangeFrom);
  if (searchParams.vocDateRangeTo)   rows = rows.filter(r => r.vocDateRange <= searchParams.vocDateRangeTo);
  if (searchParams.supplierName) rows = rows.filter(r => r.supplierName.includes(searchParams.supplierName));
  if (searchParams.materialName) rows = rows.filter(r => r.materialName.includes(searchParams.materialName));
  if (searchParams.vocStatus) rows = rows.filter(r => r.vocStatus === searchParams.vocStatus);
  if (searchParams.isUrgent) rows = rows.filter(r => r.isUrgent === searchParams.isUrgent);
  return rows;
});

const pagedRows = computed<RowItem[]>(() =>
  filteredRows.value.slice(state.page.first, state.page.first + state.pageSize)
);

// ─────────────────── Handlers ───────────────────────────────────────────────────────
function onSearch(): void {
  state.page        = { first: 0, rows: state.pageSize };
  state.selectedRow = null;
}

function onReset(): void {
  Object.assign(searchParams, { vocDateRangeFrom: '', vocDateRangeTo: '', supplierName: '', materialName: '', vocStatus: '', isUrgent: '' });
  onSearch();
}

function onRowSelect(event: { data: RowItem }): void {
  state.selectedRow = event.data;
}

function onPageChange(event: { first: number; rows: number }): void {
  state.page = event;
}

function onEdit(): void {
  // TODO: 수정 화면으로 이동 또는 모달 오픈
  console.log('[scaffold] onEdit →', state.selectedRow);
}

function onDelete(): void {
  if (!state.selectedRow) return;
  allRows.value     = allRows.value.filter(r => r.id !== state.selectedRow!.id);
  state.selectedRow = null;
}
